def solution(input_str):
    import sys

    def parse_input(input_str):
        data = input_str.strip().split()
        n, m, k, q = int(data[0]), int(data[1]), int(data[2]), int(data[3])
        treasures = [(int(data[index + 4]), int(data[index + 5])) for index in range(k)]
        safe_columns = list(map(int, data[-q:]))
        return n, m, q, treasures, safe_columns

    def is_safety(row, col, treasures, safe_columns):
        for r, c in treasures:
            # If the treasure is already collected, skip it for future checks
            if (r, c) == (row, col):
                continue
            if r > row and c in safe_columns:
                return True
        return False

    def calculate_moves(n, m, treasures, safe_columns):
        moves = 0
        current_position = []
        for row in range(1, n + 1):
            moves += row  # Moving up to row `row`
            while len(current_position) > 0:
                r, c = current_position.pop()
                if r == row:
                    moves -= 1  # Avoiding double-counting
                if is_safety(row, c, treasures, safe_columns) and (row, c) != (current_position[-1][0], current_position[-1][1]):
                    moves += 1  # Going to the next treasure in this row
                    current_position.append((row, c))

            for r, c in treasures:
                if r == row:
                    if (col := next((ci for ci, val in enumerate(current_position) if val[0] == r and val[1] == c), c != c)):  # Custom Sentinel
                        pass  # Already collected; ignore duplicates
                    else:
                        current_position.append((r, c))

        return moves

    n, m, q, treasures, safe_columns = parse_input(input_str)
    return str(calculate_moves(n, m, treasures, safe_columns)) + '\n'

